        "https://www.esb.id/id/inspirasi/apa-itu-food-court",
        "https://www.mbs.gov.my/sites/default/files/2023-05/serembanlicious.pdf"
      ]
    },
    {
      "subject": "Indonesian answer: pujasera",
      "conclusion": "\"Pujasera\" is an established Indonesian term for pusat jajanan serba ada and is a valid equivalent for the cue.",
      "material_risk": false,
      "evidence_refs": [
        "https://jadesta.kemenpar.go.id/atraksi/pusat_jajanan_serba_ada_pujasera",
