      ]
    },
    {
      "subject": "Malaysian Malay answer: medan selera",
      "conclusion": "\"Medan selera\" is an established Malaysian Malay term for a food court/shared eating area and is a valid equivalent for the cue.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=384984&keyword=medan+selera",
        "https://www.mbsj.gov.my/ms/premis-makanan-restoran-gred-ogos-2020"
      ]
    },
    {
      "subject": "Final relation and national split",
      "conclusion": "\"Different-common-word\" is too strong as the final relation without qualification. The localized answers differ, but \"food court\" is also an ordinary shared form across both varieties; the card should be treated as a shared-synonym/local-preference contrast.",
      "material_risk": true,
      "evidence_refs": [
        "https://www.esb.id/id/inspirasi/apa-itu-food-court",
        "https://www.mbs.gov.my/sites/default/files/2023-05/serembanlicious.pdf",
        "https://www.mbsj.gov.my/ms/premis-makanan-restoran-gred-ogos-2020"
      ]
    },
    {
      "subject": "False-friend contrast",
